<?php if (!defined('ABSPATH')) { exit; } ?><!doctype html>
<html <?php language_attributes(); ?>><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ورود به پنل کافه</title><style>
:root{--espresso:#211b14;--olive:#5e6d42;--cream:#f4efe5;--paper:#fffdf8;--muted:#796f61;--line:#e5ddd0}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at top right,#ebe1ce,transparent 35%),var(--cream);font-family:"Vazirmatn",Tahoma,Arial,sans-serif;color:var(--espresso);display:grid;place-items:center;padding:24px}.login{width:min(420px,100%);background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:34px;box-shadow:0 24px 70px rgba(50,39,25,.12)}.logo{width:52px;height:52px;border-radius:16px;background:var(--espresso);color:#f7f0e2;display:grid;place-items:center;font-size:23px;margin-bottom:20px}.eyebrow{font-size:12px;color:var(--olive);font-weight:700;letter-spacing:.08em;text-transform:uppercase}.title{font-size:28px;font-weight:750;margin:8px 0 7px}.sub{font-size:14px;color:var(--muted);margin:0 0 25px}label{display:block;font-size:13px;font-weight:650;margin:16px 0 7px}input{width:100%;height:48px;border:1px solid var(--line);background:#faf7f0;border-radius:12px;padding:0 14px;font-size:14px;outline:none}input:focus{border-color:#94a17e;box-shadow:0 0 0 4px rgba(148,161,126,.14)}.remember{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted);margin:14px 0}.remember input{width:auto;height:auto}.btn{width:100%;height:50px;border:0;border-radius:13px;background:var(--olive);color:white;font-size:14px;font-weight:750;cursor:pointer}.error{background:#f6e1d8;color:#8b432c;padding:11px 13px;border-radius:11px;font-size:12px;margin-bottom:12px}.foot{font-size:11px;color:#9a9185;text-align:center;margin-top:18px}</style></head><body><main class="login"><div class="logo">☕</div><div class="eyebrow">Cafe Menu Manager</div><h1 class="title">ورود به پنل مدیریت</h1><p class="sub">منوی کافه، قیمت‌ها و وضعیت محصولات را از همین‌جا مدیریت کنید.</p><?php if(!empty($error)): ?><div class="error"><?php echo esc_html($error); ?></div><?php endif; ?><form method="post" action=""><label for="identifier">ایمیل یا نام کاربری</label><input id="identifier" name="identifier" autocomplete="username" required><label for="password">رمز عبور</label><input id="password" type="password" name="password" autocomplete="current-password" required><label class="remember"><input type="checkbox" name="remember" value="1"> مرا به خاطر بسپار</label><?php wp_nonce_field('cmm_login','cmm_login_nonce'); ?><button class="btn" type="submit">ورود به پنل</button></form><div class="foot">مدیریت منوی عمومی /menu</div></main></body></html>
